import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BvlN9b-o.js";const h=JSON.parse('{"title":"Project structure","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/project-structure","contentType":"concept","prev":{"text":"Quick start","link":"/en/getting-started/quickstart"},"next":{"text":"Add a business module","link":"/en/guides/new-module"}},"headers":[],"relativePath":"en/architecture/project-structure.md","filePath":"en/architecture/project-structure.md"}'),r={name:"en/architecture/project-structure.md"};function i(o,e,p,c,d,l){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="project-structure" tabindex="-1">Project structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project structure&quot;">​</a></h1><p>Put your business in a Rust Application module and connect it through the API and Worker entry points. Find these locations before writing your first endpoint.</p><h2 id="backend-map" tabindex="-1">Backend map <a class="header-anchor" href="#backend-map" aria-label="Permalink to &quot;Backend map&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/</span></span>
<span class="line"><span>  api/src/main.rs        HTTP process: configuration, pool and lifecycle</span></span>
<span class="line"><span>  api/src/lib.rs         API composition: Router, OpenAPI, module options</span></span>
<span class="line"><span>  worker/src/main.rs     Handlers, maintenance and health checks</span></span>
<span class="line"><span>crates/</span></span>
<span class="line"><span>  app/src/http.rs        RequestId, public errors and extractors</span></span>
<span class="line"><span>  app/src/modules/      SaaS Core and specific business modules</span></span>
<span class="line"><span>  platform/src/         Database, storage, mail, Redis and telemetry</span></span>
<span class="line"><span>migrations/             Explicit SQL migrations</span></span>
<span class="line"><span>apps/api/tests/         Composed application HTTP behavior</span></span>
<span class="line"><span>crates/app/tests/       Core public capabilities and domain rules</span></span>
<span class="line"><span>examples/               Example ownership and teaching source</span></span>
<span class="line"><span>packages/contracts/     Protocol generated from Rust OpenAPI</span></span>
<span class="line"><span>packages/sdk/           Generated client and small transport setup</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/README.md" target="_blank" rel="noreferrer">README</a> covers the complete client, deployment and documentation layout. This page focuses on backend development.</p><h2 id="where-a-new-feature-belongs" tabindex="-1">Where a new feature belongs <a class="header-anchor" href="#where-a-new-feature-belongs" aria-label="Permalink to &quot;Where a new feature belongs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Location</th><th>Responsibility</th></tr></thead><tbody><tr><td>Add ticket business</td><td><code>crates/app/src/modules/tickets/</code></td><td>Entities, rules, use cases, HTTP and public interfaces</td></tr><tr><td>Declare the module</td><td><code>crates/app/src/modules/mod.rs</code></td><td>Rust module entry</td></tr><tr><td>Add tables</td><td><code>migrations/</code> and module <code>module.json</code></td><td>SQL migrations and table ownership</td></tr><tr><td>Compose the API</td><td><code>apps/api/src/lib.rs</code></td><td>Business Router, OpenAPI and supported scopes</td></tr><tr><td>Add background work</td><td><code>apps/worker/src/main.rs</code></td><td>Business Handler and maintenance registration</td></tr><tr><td>Verify behavior</td><td><code>apps/api/tests/</code></td><td>Requests, responses, permissions, persistence and failures</td></tr><tr><td>Connect clients</td><td><code>packages/contracts/</code>, <code>packages/sdk/</code></td><td>Generated protocol and methods</td></tr></tbody></table><p><code>tickets</code> is the business you will add. The default template already registers the knowledge example; both can share SaaS Core.</p><h2 id="request-responsibilities" tabindex="-1">Request responsibilities <a class="header-anchor" href="#request-responsibilities" aria-label="Permalink to &quot;Request responsibilities&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP request</span></span>
<span class="line"><span>  → composed application Router</span></span>
<span class="line"><span>  → module HTTP boundary: DTO, extractor, error mapping</span></span>
<span class="line"><span>  → Application: authorization, transaction, public capabilities</span></span>
<span class="line"><span>  → Domain rules and SQLx queries</span></span>
<span class="line"><span>  → PostgreSQL / Platform adapters</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/lib.rs" target="_blank" rel="noreferrer">Core composer</a> accepts an extra Router and a combined OpenAPI document. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/src/lib.rs" target="_blank" rel="noreferrer">API entry</a> selects the registered businesses. Core and Platform do not import a specific business.</p><p>A small module can implement one use case in <code>mod.rs</code>. Split out <code>domain.rs</code> and <code>application.rs</code> when rules and orchestration grow: Domain contains pure rules, Application owns transactions, and the HTTP boundary owns the protocol.</p><h2 id="framework-and-business-ownership" tabindex="-1">Framework and business ownership <a class="header-anchor" href="#framework-and-business-ownership" aria-label="Permalink to &quot;Framework and business ownership&quot;">​</a></h2><p>SaaS Core provides identity, membership, sessions, audit, idempotency, jobs, files, notifications, mail and shared HTTP capabilities. Your module defines its resources and rules and calls public interfaces within its own transaction.</p><p>For example, audit <code>append</code> accepts the caller&#39;s connection, so a business write and its audit commit together. Uploads and mail delivery involve I/O outside the database and need explicit publication, jobs and recovery.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>The check verifies package dependencies, table ownership, infrastructure imports in pure Domain code and example manifests. Real HTTP tests verify permission and transaction behavior. See <a href="./boundaries">Core and business boundaries</a>.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p><a href="./../guides/new-module">Add a business module</a>: create a complete Rust file, register Router and OpenAPI, and verify the result over HTTP.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/architecture/project-structure.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,21)])])}const b=a(r,[["render",i]]);export{h as __pageData,b as default};
